package pro.aanba.tv;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
final class YoutubeScreen {
 final MainActivity a;YoutubeScreen(MainActivity a){this.a=a;}
 void render(){if(a.youtubeScreen!=this||a.watching!=null)return;Object restore=a.getCurrentFocus()==null?null:a.getCurrentFocus().getTag();a.root=new FrameLayout(a);a.root.setBackgroundColor(MainActivity.BG);a.setContentView(a.root);LinearLayout page=a.column();page.setPadding(a.dp(28),a.dp(18),a.dp(28),a.dp(18));a.root.addView(page,new FrameLayout.LayoutParams(-1,-1));LinearLayout top=a.row();top.setGravity(Gravity.CENTER_VERTICAL);page.addView(top);top.addView(a.button("‹ К матчам","yt-back",this::close));a.gap(top,18);top.addView(a.text("AANBA на YouTube",23,MainActivity.TEXT,true));top.addView(new Space(a),new LinearLayout.LayoutParams(0,1,1));top.addView(a.smallButton("Канал ↗","yt-channel",()->a.openYoutube(SafeLinks.YOUTUBE_CHANNEL)));a.gap(top,8);top.addView(a.smallButton("Обновить","yt-refresh",()->a.loadYoutube(true)));a.gap(page,10);page.addView(a.text(a.youtubeMessage.isEmpty()?"Последние видео канала · открываются в приложении YouTube":a.youtubeMessage,10,MainActivity.MUTED,false));a.gap(page,14);
  ScrollView scroll=new ScrollView(a);scroll.setVerticalScrollBarEnabled(false);page.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout grid=a.column();scroll.addView(grid);if(a.youtube==null)grid.addView(a.text("Лента недоступна. Кнопка «Канал» откроет AANBA в YouTube.",16,MainActivity.MUTED,false));else{LinearLayout row=null;int n=0;for(YoutubeFeed.Video video:a.youtube.videos){if(n%4==0){row=a.row();LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.bottomMargin=a.dp(14);grid.addView(row,rp);}LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(0,-2,1);cp.rightMargin=n%4<3?a.dp(12):0;row.addView(card(a,video,false),cp);n++;}if(row!=null)while(n++%4!=0)row.addView(new Space(a),new LinearLayout.LayoutParams(0,1,1));}
  a.focusMotion=new FocusMotion(a,a.root);a.root.addView(a.focusMotion,new FrameLayout.LayoutParams(-1,-1));a.root.getViewTreeObserver().addOnGlobalFocusChangeListener((old,next)->{if(next==null||!(next.getTag() instanceof String)||!((String)next.getTag()).startsWith("yt:"))a.focusMotion.hide();});View focus=restore==null?null:a.root.findViewWithTag(restore);if(focus!=null)focus.requestFocus();else a.root.findViewWithTag("yt-back").requestFocus();UiMotion.enter(page,a.dp(5));
 }
 void close(){a.youtubeScreen=null;a.renderHome();}
 static LinearLayout card(MainActivity a,YoutubeFeed.Video video,boolean compact){
  LinearLayout card=compact?a.row():a.column();card.setTag("yt:"+video.id);card.setFocusable(true);card.setFocusableInTouchMode(true);card.setClickable(true);card.setContentDescription("YouTube AANBA: "+video.title);card.setPadding(a.dp(7),a.dp(7),a.dp(7),a.dp(7));GradientDrawable bg=a.round(0xff20232c,12);card.setBackground(bg);card.setOnFocusChangeListener((v,f)->{bg.setStroke(a.dp(f?2:0),MainActivity.TEXT);if(f&&a.focusMotion!=null)a.focusMotion.move(v);});card.setOnClickListener(v->a.openYoutube(video.watchUrl()));
  ImageView image=compact?new ImageView(a):new Thumbnail(a);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(a.round(0xff303643,8));image.setClipToOutline(true);image.setContentDescription(video.displayTitle());if(compact){card.addView(image,new LinearLayout.LayoutParams(a.dp(112),a.dp(63)));a.gap(card,9);}else card.addView(image,new LinearLayout.LayoutParams(-1,-2));
  LinearLayout info=a.column();if(compact)card.addView(info,new LinearLayout.LayoutParams(0,-1,1));else{a.gap(card,7);card.addView(info,new LinearLayout.LayoutParams(-1,-2));}TextView title=a.text(video.displayTitle(),compact?10:11,MainActivity.TEXT,true);title.setMaxLines(compact?3:2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);info.addView(title,new LinearLayout.LayoutParams(-1,compact?0:a.dp(29),compact?1:0));TextView date=a.text("YouTube · "+DateTimeFormatter.ofPattern("d MMM",new Locale("ru")).withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(video.published)),9,MainActivity.MUTED,false);date.setPadding(0,a.dp(4),0,0);info.addView(date);a.thumbnails.load(video.thumbnail,image);return card;
 }
 static final class Thumbnail extends ImageView{Thumbnail(MainActivity a){super(a);}@Override protected void onMeasure(int width,int height){int w=MeasureSpec.getSize(width);super.onMeasure(width,MeasureSpec.makeMeasureSpec(Math.round(w*9f/16),MeasureSpec.EXACTLY));}}
}
